#AVAWHSRF
/// <summary>
/// The <c>AVAWHSControlFullMode</c> class is responsible for handling the full mode validation
/// </summary>
[
    WhsControlFactory(#AVAFullMode)
]
final class AVAWHSControlFullMode extends WHSControl
{
}

Method.Source:
/// <summary>
/// process the Control logic
/// </summary>
/// <returns>
/// return true if process complete
/// </returns>
public boolean process()
{
    boolean valid;

    valid = this.checkFieldSelection(this.parmData());

    if (valid)
    {
        fieldValues.insert(ProcessGuideDataTypeNames::AVAFullMode, this.parmData());
    }

    return valid;       
}

private boolean checkFieldSelection(str _checkStr)
{
    boolean ret;

    ret = WHSWorkException::exist(_checkStr, WHSExceptionType::AVAFullPick);

    return ret;
}
